from pathlib import Path
import py_compile
import shutil
import sys

ROOT = Path.cwd()
ANALYZER = ROOT / "analyzer"

components_target = ANALYZER / "components.py"
value_target = ANALYZER / "value.py"

if not ANALYZER.is_dir():
    raise SystemExit(
        "ERREUR: dossier analyzer introuvable. "
        "Lance ce script depuis la racine du projet PC Hunter."
    )

if not components_target.exists() or not value_target.exists():
    raise SystemExit(
        "ERREUR: analyzer/components.py ou analyzer/value.py introuvable."
    )

# Sauvegardes avant remplacement
components_backup = ANALYZER / "components.py.bak_before_portables"
value_backup = ANALYZER / "value.py.bak_before_portables"

shutil.copy2(components_target, components_backup)
shutil.copy2(value_target, value_backup)

COMPONENTS_CODE = 'import re\nimport unicodedata\n\n\n# ============================================================\n# PC HUNTER - EXTRACTION DES COMPOSANTS\n# ============================================================\n\n\ndef normaliser_texte(texte):\n    """\n    Rend le texte vendeur plus régulier pour les regex.\n\n    Exemples tolérés :\n    Rysen -> Ryzen\n    Rizen -> Ryzen\n    Ge Force -> GeForce\n    N Vidia -> Nvidia\n    tmi3 -> i3\n    Giga -> Go\n    """\n\n    texte = str(\n        texte or ""\n    )\n\n    texte = unicodedata.normalize(\n        "NFKD",\n        texte,\n    )\n\n    texte = "".join(\n        caractere\n        for caractere in texte\n        if not unicodedata.combining(\n            caractere\n        )\n    )\n\n    texte = texte.lower()\n\n    corrections = {\n        "rysen": "ryzen",\n        "rizen": "ryzen",\n        "raizen": "ryzen",\n        "ge force": "geforce",\n        "n vidia": "nvidia",\n        "tmi3": "i3",\n        "tmi5": "i5",\n        "tmi7": "i7",\n        "giga octets": "go",\n        "gigaoctets": "go",\n        "giga": "go",\n    }\n\n    for ancien, nouveau in (\n        corrections.items()\n    ):\n        texte = texte.replace(\n            ancien,\n            nouveau,\n        )\n\n    texte = re.sub(\n        r"\\s+",\n        " ",\n        texte,\n    )\n\n    return texte.strip()\n\n\ndef texte_annonce(annonce):\n    return normaliser_texte(\n        " ".join(\n            [\n                str(\n                    getattr(\n                        annonce,\n                        "titre",\n                        "",\n                    )\n                    or ""\n                ),\n                str(\n                    getattr(\n                        annonce,\n                        "description",\n                        "",\n                    )\n                    or ""\n                ),\n            ]\n        )\n    )\n\n\ndef ajouter_unique(\n    liste,\n    valeur,\n):\n    if (\n        valeur\n        and\n        valeur not in liste\n    ):\n        liste.append(\n            valeur\n        )\n\n\n# ============================================================\n# GPU NVIDIA / AMD\n# ============================================================\n\ndef detecter_gpu(texte):\n    resultats = []\n\n    # RTX 2060 / 3060 Ti / 4070 Super...\n    for match in re.finditer(\n        r"\\b(?:nvidia\\s+)?"\n        r"(?:geforce\\s+)?"\n        r"rtx\\s*"\n        r"([2-5]\\d{3})"\n        r"\\s*(ti|super)?\\b",\n        texte,\n        flags=re.IGNORECASE,\n    ):\n        modele = match.group(1)\n        suffixe = match.group(2)\n\n        valeur = (\n            f"RTX {modele}"\n        )\n\n        if suffixe:\n            if (\n                suffixe.lower()\n                == "ti"\n            ):\n                valeur += " Ti"\n\n            else:\n                valeur += " Super"\n\n        ajouter_unique(\n            resultats,\n            valeur,\n        )\n\n    # GTX 960M / 1050 Ti / 1660 Super...\n    for match in re.finditer(\n        r"\\b(?:nvidia\\s+)?"\n        r"(?:geforce\\s+)?"\n        r"gtx\\s*"\n        r"(\\d{3,4})"\n        r"\\s*(ti|super|m)?\\b",\n        texte,\n        flags=re.IGNORECASE,\n    ):\n        modele = match.group(1)\n        suffixe = match.group(2)\n\n        valeur = (\n            f"GTX {modele}"\n        )\n\n        if suffixe:\n            suffixe = (\n                suffixe.lower()\n            )\n\n            if suffixe == "ti":\n                valeur += " Ti"\n\n            elif suffixe == "super":\n                valeur += " Super"\n\n            elif suffixe == "m":\n                valeur += "M"\n\n        ajouter_unique(\n            resultats,\n            valeur,\n        )\n\n    # RX 6600 / 6700 XT / 7900 XTX...\n    for match in re.finditer(\n        r"\\b(?:amd\\s+)?"\n        r"(?:radeon\\s+)?"\n        r"rx\\s*"\n        r"(\\d{3,4})"\n        r"\\s*(xtx|xt|m)?\\b",\n        texte,\n        flags=re.IGNORECASE,\n    ):\n        modele = match.group(1)\n        suffixe = match.group(2)\n\n        valeur = (\n            f"RX {modele}"\n        )\n\n        if suffixe:\n            valeur += (\n                " "\n                + suffixe.upper()\n            )\n\n        ajouter_unique(\n            resultats,\n            valeur,\n        )\n\n    return resultats\n\n\n# ============================================================\n# CPU INTEL / AMD\n# ============================================================\n\ndef detecter_cpu(texte):\n    resultats = []\n\n    # i5-13400F / i7 6700HQ / i5-10400...\n    for match in re.finditer(\n        r"\\b(?:intel\\s+)?"\n        r"(?:core\\s+)?"\n        r"(i[3579])"\n        r"[\\s\\-]*"\n        r"(\\d{4,5})"\n        r"\\s*"\n        r"([a-z]{0,3})\\b",\n        texte,\n        flags=re.IGNORECASE,\n    ):\n        famille = (\n            match.group(1)\n            .lower()\n        )\n\n        modele = (\n            match.group(2)\n        )\n\n        suffixe = (\n            match.group(3)\n            or ""\n        ).upper()\n\n        valeur = (\n            f"{famille}-"\n            f"{modele}"\n            f"{suffixe}"\n        )\n\n        ajouter_unique(\n            resultats,\n            valeur,\n        )\n\n    # Ryzen 5 5600 / Ryzen 7 5800X / 7840HS...\n    for match in re.finditer(\n        r"\\bryzen\\s*"\n        r"([3579])"\n        r"\\s*"\n        r"(\\d{4,5})"\n        r"\\s*"\n        r"([a-z]{0,3})\\b",\n        texte,\n        flags=re.IGNORECASE,\n    ):\n        gamme = match.group(1)\n        modele = match.group(2)\n\n        suffixe = (\n            match.group(3)\n            or ""\n        ).upper()\n\n        valeur = (\n            f"Ryzen {gamme} "\n            f"{modele}"\n            f"{suffixe}"\n        )\n\n        ajouter_unique(\n            resultats,\n            valeur,\n        )\n\n    return resultats\n\n\n# ============================================================\n# APPLE SILICON\n# ============================================================\n\ndef detecter_puce_apple(texte):\n    resultats = []\n\n    for match in re.finditer(\n        r"\\b(?:apple\\s+)?"\n        r"(m[1-5])"\n        r"\\s*(pro|max|ultra)?\\b",\n        texte,\n        flags=re.IGNORECASE,\n    ):\n        puce = (\n            match.group(1)\n            .upper()\n        )\n\n        suffixe = (\n            match.group(2)\n        )\n\n        if suffixe:\n            puce += (\n                " "\n                + suffixe.title()\n            )\n\n        ajouter_unique(\n            resultats,\n            puce,\n        )\n\n    return resultats\n\n\n# ============================================================\n# RAM\n# ============================================================\n\ndef detecter_ram(texte):\n    resultats = []\n\n    capacites = (\n        "4|6|8|12|16|18|24|32|"\n        "36|48|64|96|128"\n    )\n\n    motifs = [\n        (\n            rf"\\b({capacites})\\s*"\n            r"(?:go|gb)"\n            r"\\s*(ddr[345])?"\n            r"(?:\\s*(?:de\\s+)?ram)?\\b"\n        ),\n        (\n            r"\\b(?:ram|memoire(?:\\s+vive)?)"\n            r"\\s*[:\\-]?\\s*"\n            rf"({capacites})\\s*"\n            r"(?:go|gb)"\n            r"\\s*(ddr[345])?\\b"\n        ),\n    ]\n\n    candidats = []\n\n    for motif in motifs:\n        for match in re.finditer(\n            motif,\n            texte,\n            flags=re.IGNORECASE,\n        ):\n            nombre = (\n                match.group(1)\n            )\n\n            ddr = (\n                match.group(2)\n                if (\n                    match.lastindex\n                    and\n                    match.lastindex >= 2\n                )\n                else None\n            )\n\n            debut = max(\n                0,\n                match.start() - 25,\n            )\n\n            fin = min(\n                len(texte),\n                match.end() + 25,\n            )\n\n            contexte = texte[\n                debut:fin\n            ]\n\n            if (\n                (\n                    "ssd" in contexte\n                    or\n                    "nvme" in contexte\n                    or\n                    "disque" in contexte\n                    or\n                    "stockage" in contexte\n                )\n                and not (\n                    "ram" in contexte\n                    or\n                    "memoire" in contexte\n                    or\n                    "ddr" in contexte\n                )\n            ):\n                continue\n\n            score = 0\n\n            if (\n                "ram" in contexte\n                or\n                "memoire" in contexte\n            ):\n                score += 3\n\n            if ddr:\n                score += 2\n\n            candidats.append(\n                (\n                    score,\n                    nombre,\n                    ddr,\n                )\n            )\n\n    if not candidats:\n        return resultats\n\n    candidats.sort(\n        key=lambda item: item[0],\n        reverse=True,\n    )\n\n    (\n        _,\n        nombre,\n        ddr,\n    ) = candidats[0]\n\n    valeur = (\n        f"{nombre} Go"\n    )\n\n    if ddr:\n        valeur += (\n            " "\n            + ddr.upper()\n        )\n\n    ajouter_unique(\n        resultats,\n        valeur,\n    )\n\n    return resultats\n\n\n# ============================================================\n# STOCKAGE\n# ============================================================\n\ndef normaliser_capacite_stockage(\n    nombre,\n    unite,\n):\n    nombre = str(\n        nombre\n    ).replace(\n        ",",\n        ".",\n    )\n\n    try:\n        valeur = float(\n            nombre\n        )\n\n    except ValueError:\n        return (\n            f"{nombre} "\n            f"{str(unite).upper()}"\n        )\n\n    unite = str(\n        unite\n    ).lower()\n\n    if unite in {\n        "to",\n        "tb",\n    }:\n        if valeur.is_integer():\n            valeur = int(\n                valeur\n            )\n\n        return (\n            f"{valeur} To"\n        )\n\n    if valeur.is_integer():\n        valeur = int(\n            valeur\n        )\n\n    return (\n        f"{valeur} Go"\n    )\n\n\ndef detecter_stockage(texte):\n    resultats = []\n\n    # NVMe\n    match = re.search(\n        r"\\bnvme\\b"\n        r"(?:\\s*(?:de\\s+)?)?"\n        r"(\\d+(?:[.,]\\d+)?)?"\n        r"\\s*(to|tb|go|gb)?",\n        texte,\n        flags=re.IGNORECASE,\n    )\n\n    if match:\n        valeur = "NVMe"\n\n        if (\n            match.group(1)\n            and\n            match.group(2)\n        ):\n            valeur += (\n                " "\n                + normaliser_capacite_stockage(\n                    match.group(1),\n                    match.group(2),\n                )\n            )\n\n        ajouter_unique(\n            resultats,\n            valeur,\n        )\n\n    # SSD\n    match = re.search(\n        r"\\bssd\\b"\n        r"(?:\\s*(?:de\\s+)?)?"\n        r"(\\d+(?:[.,]\\d+)?)?"\n        r"\\s*(to|tb|go|gb)?",\n        texte,\n        flags=re.IGNORECASE,\n    )\n\n    if match:\n        valeur = "SSD"\n\n        if (\n            match.group(1)\n            and\n            match.group(2)\n        ):\n            valeur += (\n                " "\n                + normaliser_capacite_stockage(\n                    match.group(1),\n                    match.group(2),\n                )\n            )\n\n        ajouter_unique(\n            resultats,\n            valeur,\n        )\n\n    # HDD / disque dur\n    match = re.search(\n        r"\\b(?:hdd|disque\\s+dur)\\b"\n        r"(?:\\s*(?:de\\s+)?)?"\n        r"(\\d+(?:[.,]\\d+)?)?"\n        r"\\s*(to|tb|go|gb)?",\n        texte,\n        flags=re.IGNORECASE,\n    )\n\n    if match:\n        valeur = "HDD"\n\n        if (\n            match.group(1)\n            and\n            match.group(2)\n        ):\n            valeur += (\n                " "\n                + normaliser_capacite_stockage(\n                    match.group(1),\n                    match.group(2),\n                )\n            )\n\n        ajouter_unique(\n            resultats,\n            valeur,\n        )\n\n    return resultats\n\n\ndef detecter_stockage_generique(\n    texte,\n):\n    """\n    Utile surtout pour les Mac :\n    \'stockage 512 Go\'\n    \'capacité 750 Go\'\n    \'1 To de stockage\'\n    """\n\n    motifs = [\n        (\n            r"\\b(?:stockage|capacite|disque)"\n            r"\\s*[:\\-]?\\s*"\n            r"(\\d+(?:[.,]\\d+)?)"\n            r"\\s*(to|tb|go|gb)\\b"\n        ),\n        (\n            r"\\b(\\d+(?:[.,]\\d+)?)"\n            r"\\s*(to|tb|go|gb)"\n            r"\\s+(?:de\\s+)?"\n            r"(?:stockage|capacite|disque)\\b"\n        ),\n    ]\n\n    for motif in motifs:\n        match = re.search(\n            motif,\n            texte,\n            flags=re.IGNORECASE,\n        )\n\n        if match:\n            return normaliser_capacite_stockage(\n                match.group(1),\n                match.group(2),\n            )\n\n    return None\n\n\n# ============================================================\n# MACHINE APPLE\n# ============================================================\n\ndef detecter_machine_apple(annonce):\n    texte = texte_annonce(\n        annonce\n    )\n\n    modele = None\n\n    if re.search(\n        r"\\bmac\\s*book\\s+air\\b",\n        texte,\n    ):\n        modele = "MacBook Air"\n\n    elif re.search(\n        r"\\bmac\\s*book\\s+pro\\b",\n        texte,\n    ):\n        modele = "MacBook Pro"\n\n    elif re.search(\n        r"\\bimac\\b",\n        texte,\n    ):\n        modele = "iMac"\n\n    elif re.search(\n        r"\\bmac\\s*mini\\b",\n        texte,\n    ):\n        modele = "Mac mini"\n\n    elif re.search(\n        r"\\bmac\\s*studio\\b",\n        texte,\n    ):\n        modele = "Mac Studio"\n\n    elif re.search(\n        r"\\bmac\\s+pro\\b",\n        texte,\n    ):\n        modele = "Mac Pro"\n\n    if modele is None:\n        return None\n\n    annees = [\n        int(valeur)\n        for valeur in re.findall(\n            r"\\b(20(?:0[8-9]|1\\d|2[0-6]))\\b",\n            texte,\n        )\n    ]\n\n    annee = (\n        max(annees)\n        if annees\n        else None\n    )\n\n    puces = detecter_puce_apple(\n        texte\n    )\n\n    puce = (\n        puces[0]\n        if puces\n        else None\n    )\n\n    cpus = detecter_cpu(\n        texte\n    )\n\n    cpu = (\n        cpus[0]\n        if cpus\n        else None\n    )\n\n    ram = detecter_ram(\n        texte\n    )\n\n    stockage_liste = (\n        detecter_stockage(\n            texte\n        )\n    )\n\n    stockage = (\n        stockage_liste[0]\n        if stockage_liste\n        else detecter_stockage_generique(\n            texte\n        )\n    )\n\n    ecran = None\n\n    match_ecran = re.search(\n        r"\\b("\n        r"11|12|13|14|15|16|"\n        r"21(?:[.,]5)?|24|27"\n        r")\\s*"\n        r"(?:pouces?|\\"|inch)\\b",\n        texte,\n        flags=re.IGNORECASE,\n    )\n\n    if match_ecran:\n        ecran = (\n            match_ecran.group(1)\n            .replace(\n                ",",\n                ".",\n            )\n            + " pouces"\n        )\n\n    return {\n        "modele":\n            modele,\n\n        "annee":\n            annee,\n\n        "puce":\n            puce,\n\n        "cpu":\n            cpu,\n\n        "ram":\n            (\n                ram[0]\n                if ram\n                else None\n            ),\n\n        "stockage":\n            stockage,\n\n        "ecran":\n            ecran,\n    }\n\n\n\n\n# ============================================================\n# MACHINE PORTABLE WINDOWS\n# ============================================================\n\ndef detecter_taille_ecran_portable(texte):\n    match = re.search(\n        r"\\b("\n        r"11(?:[.,]6)?|12(?:[.,]5)?|13(?:[.,]3)?|14|"\n        r"15(?:[.,]6)?|16|17(?:[.,]3)?|18"\n        r")\\s*(?:pouces?|\\"|inch)\\b",\n        texte,\n        flags=re.IGNORECASE,\n    )\n\n    if not match:\n        return None\n\n    return (\n        match.group(1)\n        .replace(",", ".")\n        + " pouces"\n    )\n\n\ndef detecter_frequence_ecran(texte):\n    match = re.search(\n        r"\\b(60|75|90|120|144|165|180|240|300|360)"\n        r"\\s*hz\\b",\n        texte,\n        flags=re.IGNORECASE,\n    )\n\n    if not match:\n        return None\n\n    return (\n        match.group(1)\n        + " Hz"\n    )\n\n\ndef detecter_machine_portable_windows(annonce):\n    texte = texte_annonce(\n        annonce\n    )\n\n    # Apple est traité par son moteur dédié.\n    if any(\n        mot in texte\n        for mot in (\n            "macbook",\n            "imac",\n            "mac mini",\n            "mac studio",\n        )\n    ):\n        return None\n\n    indices_portable = (\n        "pc portable",\n        "ordinateur portable",\n        "laptop",\n        "notebook",\n        "asus rog",\n        "rog strix",\n        "rog zephyrus",\n        "asus tuf",\n        "lenovo legion",\n        "ideapad gaming",\n        "hp omen",\n        "hp victus",\n        "hp pavilion gaming",\n        "hp pavilion gamer",\n        "pavilion gamer",\n        "acer nitro",\n        "acer predator",\n        "msi katana",\n        "msi pulse",\n        "msi gf",\n        "msi gl",\n        "msi gs",\n        "dell g15",\n        "dell g5",\n        "dell xps",\n        "alienware",\n        "razer blade",\n        "gigabyte aorus",\n    )\n\n    if not any(\n        indice in texte\n        for indice in indices_portable\n    ):\n        return None\n\n    marque = None\n\n    marques = {\n        "asus": "ASUS",\n        "hp": "HP",\n        "hewlett packard": "HP",\n        "dell": "Dell",\n        "lenovo": "Lenovo",\n        "acer": "Acer",\n        "msi": "MSI",\n        "gigabyte": "Gigabyte",\n        "aorus": "Gigabyte",\n        "razer": "Razer",\n        "medion": "Medion",\n        "alienware": "Alienware",\n    }\n\n    for cle, nom in marques.items():\n        if re.search(\n            rf"\\b{re.escape(cle)}\\b",\n            texte,\n        ):\n            marque = nom\n            break\n\n    gamme = None\n\n    gammes = (\n        ("rog zephyrus", "ROG Zephyrus"),\n        ("rog strix", "ROG Strix"),\n        ("asus rog", "ROG"),\n        ("asus tuf", "TUF"),\n        ("lenovo legion", "Legion"),\n        ("ideapad gaming", "IdeaPad Gaming"),\n        ("hp omen", "Omen"),\n        ("hp victus", "Victus"),\n        ("hp pavilion gaming", "Pavilion Gaming"),\n        ("hp pavilion gamer", "Pavilion Gaming"),\n        ("pavilion gamer", "Pavilion Gaming"),\n        ("acer predator", "Predator"),\n        ("acer nitro", "Nitro"),\n        ("msi katana", "Katana"),\n        ("msi pulse", "Pulse"),\n        ("msi gf", "GF"),\n        ("msi gl", "GL"),\n        ("msi gs", "GS"),\n        ("dell g15", "G15"),\n        ("dell g5", "G5"),\n        ("dell xps", "XPS"),\n        ("alienware", "Alienware"),\n        ("razer blade", "Blade"),\n        ("gigabyte aorus", "AORUS"),\n    )\n\n    for cle, nom in gammes:\n        if cle in texte:\n            gamme = nom\n            break\n\n    cpus = detecter_cpu(\n        texte\n    )\n\n    gpus = detecter_gpu(\n        texte\n    )\n\n    ram = detecter_ram(\n        texte\n    )\n\n    stockage = detecter_stockage(\n        texte\n    )\n\n    return {\n        "marque":\n            marque,\n\n        "gamme":\n            gamme,\n\n        "cpu":\n            (\n                cpus[0]\n                if cpus\n                else None\n            ),\n\n        "gpu":\n            (\n                gpus[0]\n                if gpus\n                else None\n            ),\n\n        "ram":\n            (\n                ram[0]\n                if ram\n                else None\n            ),\n\n        "stockage":\n            (\n                stockage[0]\n                if stockage\n                else None\n            ),\n\n        "ecran":\n            detecter_taille_ecran_portable(\n                texte\n            ),\n\n        "frequence_ecran":\n            detecter_frequence_ecran(\n                texte\n            ),\n    }\n\n\n# ============================================================\n# DETECTION GENERALE\n# ============================================================\n\ndef detecter_composants(annonce):\n    texte = texte_annonce(\n        annonce\n    )\n\n    detection = {\n        "gpu":\n            detecter_gpu(\n                texte\n            ),\n\n        "cpu":\n            detecter_cpu(\n                texte\n            ),\n\n        "ram":\n            detecter_ram(\n                texte\n            ),\n\n        "stockage":\n            detecter_stockage(\n                texte\n            ),\n\n        "apple_chip":\n            detecter_puce_apple(\n                texte\n            ),\n    }\n\n    machine_apple = (\n        detecter_machine_apple(\n            annonce\n        )\n    )\n\n    if machine_apple:\n        detection[\n            "machine_apple"\n        ] = machine_apple\n\n    machine_portable_windows = (\n        detecter_machine_portable_windows(\n            annonce\n        )\n    )\n\n    if machine_portable_windows:\n        detection[\n            "machine_portable_windows"\n        ] = machine_portable_windows\n\n    return detection\n'
VALUE_CODE = 'import re\nimport unicodedata\n\nfrom database.price import PRIX_COMPOSANTS\n\nfrom analyzer.components import (\n    detecter_composants,\n    detecter_machine_apple,\n    detecter_machine_portable_windows,\n    texte_annonce,\n)\n\nfrom analyzer.consistency import (\n    verifier_coherence,\n)\n\n\nCATEGORIES_PRINCIPALES = {\n    "gpu",\n    "cpu",\n    "ram",\n    "stockage",\n}\n\n\n# ============================================================\n# REFERENCES APPLE INTERNES - VERSION 1\n#\n# IMPORTANT :\n# Ce ne sont PAS des cotations live.\n# Ce sont des bases prudentes de machine COMPLETE d\'occasion.\n#\n# PC Hunter pourra ensuite remplacer ces bases par des\n# comparables réels issus de son historique de marché.\n# ============================================================\n\nAPPLE_SILICON_BASE = {\n    # MacBook Air\n    ("MacBook Air", "M1"): 450,\n    ("MacBook Air", "M2"): 600,\n    ("MacBook Air", "M3"): 750,\n    ("MacBook Air", "M4"): 900,\n\n    # MacBook Pro\n    ("MacBook Pro", "M1"): 600,\n    ("MacBook Pro", "M1 Pro"): 850,\n    ("MacBook Pro", "M1 Max"): 1050,\n\n    ("MacBook Pro", "M2"): 700,\n    ("MacBook Pro", "M2 Pro"): 1000,\n    ("MacBook Pro", "M2 Max"): 1200,\n\n    ("MacBook Pro", "M3"): 900,\n    ("MacBook Pro", "M3 Pro"): 1200,\n    ("MacBook Pro", "M3 Max"): 1550,\n\n    ("MacBook Pro", "M4"): 1150,\n    ("MacBook Pro", "M4 Pro"): 1500,\n    ("MacBook Pro", "M4 Max"): 1900,\n\n    # Mac mini\n    ("Mac mini", "M1"): 330,\n    ("Mac mini", "M2"): 430,\n    ("Mac mini", "M2 Pro"): 650,\n    ("Mac mini", "M4"): 500,\n    ("Mac mini", "M4 Pro"): 850,\n\n    # iMac Apple Silicon\n    ("iMac", "M1"): 650,\n    ("iMac", "M3"): 850,\n    ("iMac", "M4"): 1000,\n\n    # Mac Studio\n    ("Mac Studio", "M1 Max"): 1000,\n    ("Mac Studio", "M1 Ultra"): 1450,\n    ("Mac Studio", "M2 Max"): 1250,\n    ("Mac Studio", "M2 Ultra"): 1800,\n}\n\n\nAPPLE_INTEL_ANNEE_BASE = {\n    "MacBook Air": {\n        2013: 140,\n        2014: 160,\n        2015: 180,\n        2016: 190,\n        2017: 210,\n        2018: 250,\n        2019: 280,\n        2020: 320,\n    },\n\n    "MacBook Pro": {\n        2012: 150,\n        2013: 180,\n        2014: 210,\n        2015: 250,\n        2016: 280,\n        2017: 320,\n        2018: 360,\n        2019: 400,\n        2020: 450,\n    },\n\n    "iMac": {\n        2009: 80,\n        2010: 110,\n        2011: 120,\n        2012: 140,\n        2013: 160,\n        2014: 180,\n        2015: 210,\n        2017: 260,\n        2019: 340,\n        2020: 430,\n    },\n\n    "Mac mini": {\n        2012: 120,\n        2014: 150,\n        2018: 260,\n    },\n}\n\n\n# ============================================================\n# NORMALISATION\n# ============================================================\n\ndef normaliser_reference(texte):\n    texte = str(\n        texte or ""\n    )\n\n    texte = unicodedata.normalize(\n        "NFKD",\n        texte,\n    )\n\n    texte = "".join(\n        caractere\n        for caractere in texte\n        if not unicodedata.combining(\n            caractere\n        )\n    )\n\n    texte = texte.lower()\n\n    return re.sub(\n        r"[^a-z0-9]+",\n        "",\n        texte,\n    )\n\n\n# ============================================================\n# RECHERCHE DANS database/price.py\n# ============================================================\n\ndef trouver_reference_prix(\n    categorie,\n    valeur_detectee,\n):\n    valeur_normalisee = (\n        normaliser_reference(\n            valeur_detectee\n        )\n    )\n\n    # Correspondance exacte CPU / GPU / RAM / stockage.\n    for composant, infos in (\n        PRIX_COMPOSANTS.items()\n    ):\n        if (\n            infos.get(\n                "categorie"\n            )\n            != categorie\n        ):\n            continue\n\n        references = [\n            composant,\n            *infos.get(\n                "aliases",\n                []\n            ),\n        ]\n\n        for reference in references:\n            if (\n                normaliser_reference(\n                    reference\n                )\n                ==\n                valeur_normalisee\n            ):\n                return (\n                    composant,\n                    infos,\n                )\n\n    # Correspondance souple UNIQUEMENT RAM / stockage.\n    #\n    # On refuse pour CPU/GPU pour éviter :\n    # i5-13400F -> mauvais "i5"\n    # RTX 4060 -> mauvaise RTX\n    if categorie not in {\n        "ram",\n        "stockage",\n    }:\n        return (\n            None,\n            None,\n        )\n\n    for composant, infos in (\n        PRIX_COMPOSANTS.items()\n    ):\n        if (\n            infos.get(\n                "categorie"\n            )\n            != categorie\n        ):\n            continue\n\n        references = [\n            composant,\n            *infos.get(\n                "aliases",\n                []\n            ),\n        ]\n\n        for reference in references:\n            reference_normalisee = (\n                normaliser_reference(\n                    reference\n                )\n            )\n\n            if (\n                reference_normalisee\n                and\n                reference_normalisee\n                in valeur_normalisee\n            ):\n                return (\n                    composant,\n                    infos,\n                )\n\n    return (\n        None,\n        None,\n    )\n\n\n# ============================================================\n# OUTILS MACHINE\n# ============================================================\n\ndef extraire_nombre_go(valeur):\n    if not valeur:\n        return None\n\n    match = re.search(\n        r"\\b(\\d+)\\s*go\\b",\n        str(valeur),\n        flags=re.IGNORECASE,\n    )\n\n    if not match:\n        return None\n\n    try:\n        return int(\n            match.group(1)\n        )\n\n    except ValueError:\n        return None\n\n\ndef stockage_en_go(valeur):\n    if not valeur:\n        return None\n\n    texte = str(\n        valeur\n    ).lower()\n\n    match_to = re.search(\n        r"(\\d+(?:[.,]\\d+)?)"\n        r"\\s*to\\b",\n        texte,\n    )\n\n    if match_to:\n        try:\n            return int(\n                float(\n                    match_to.group(1)\n                    .replace(\n                        ",",\n                        ".",\n                    )\n                )\n                * 1024\n            )\n\n        except ValueError:\n            return None\n\n    match_go = re.search(\n        r"(\\d+)\\s*go\\b",\n        texte,\n    )\n\n    if match_go:\n        try:\n            return int(\n                match_go.group(1)\n            )\n\n        except ValueError:\n            return None\n\n    return None\n\n\ndef est_portable_windows(annonce):\n    texte = texte_annonce(\n        annonce\n    )\n\n    mots = (\n        "pc portable",\n        "ordinateur portable",\n        "laptop",\n        "notebook",\n        "asus rog",\n        "lenovo legion",\n        "hp pavilion",\n        "hp omen",\n        "hp victus",\n        "acer nitro",\n        "msi katana",\n        "msi pulse",\n    )\n\n    return any(\n        mot in texte\n        for mot in mots\n    )\n\n\ndef est_tout_en_un(annonce):\n    texte = texte_annonce(\n        annonce\n    )\n\n    return (\n        "tout en un" in texte\n        or\n        "all in one" in texte\n        or\n        "all-in-one" in texte\n    )\n\n\ndef est_gaming(annonce):\n    texte = texte_annonce(\n        annonce\n    )\n\n    return any(\n        mot in texte\n        for mot in (\n            "gaming",\n            "gamer",\n            "jeu video",\n            "jeux video",\n        )\n    )\n\n\n# ============================================================\n# AJUSTEMENTS APPLE\n# ============================================================\n\ndef ajustement_ram_apple(ram):\n    quantite = extraire_nombre_go(\n        ram\n    )\n\n    if quantite is None:\n        return 0\n\n    if quantite >= 64:\n        return 260\n\n    if quantite >= 48:\n        return 220\n\n    if quantite >= 32:\n        return 170\n\n    if quantite >= 24:\n        return 120\n\n    if quantite >= 16:\n        return 70\n\n    return 0\n\n\ndef ajustement_stockage_apple(\n    stockage,\n    puce=None,\n):\n    """\n    Sur Apple Silicon, le stockage interne est un SSD :\n    on peut appliquer un bonus de capacité.\n\n    Sur un ancien Mac Intel, une simple mention "1 To"\n    peut désigner un HDD. On ne lui donne donc PAS\n    automatiquement la valeur d\'un SSD.\n    """\n\n    if not stockage:\n        return 0\n\n    texte = str(\n        stockage\n    ).lower()\n\n    stockage_rapide_confirme = (\n        puce is not None\n        or\n        "ssd" in texte\n        or\n        "nvme" in texte\n    )\n\n    if not stockage_rapide_confirme:\n        return 0\n\n    capacite = stockage_en_go(\n        stockage\n    )\n\n    if capacite is None:\n        return 0\n\n    if capacite >= 4096:\n        return 350\n\n    if capacite >= 2048:\n        return 240\n\n    if capacite >= 1024:\n        return 140\n\n    if capacite >= 512:\n        return 70\n\n    return 0\n\n\ndef ajustement_ecran_apple(\n    modele,\n    ecran,\n):\n    if not ecran:\n        return 0\n\n    try:\n        taille = float(\n            str(ecran)\n            .replace(\n                " pouces",\n                "",\n            )\n        )\n\n    except ValueError:\n        return 0\n\n    if modele == "MacBook Pro":\n        if taille >= 16:\n            return 180\n\n        if taille >= 14:\n            return 100\n\n    if (\n        modele == "iMac"\n        and\n        taille >= 27\n    ):\n        return 70\n\n    return 0\n\n\ndef trouver_base_intel_apple(\n    modele,\n    annee,\n):\n    table = (\n        APPLE_INTEL_ANNEE_BASE.get(\n            modele\n        )\n    )\n\n    if not table:\n        return None\n\n    if annee in table:\n        return table[\n            annee\n        ]\n\n    annees = sorted(\n        table\n    )\n\n    inferieures = [\n        annee_connue\n        for annee_connue in annees\n        if annee_connue <= annee\n    ]\n\n    superieures = [\n        annee_connue\n        for annee_connue in annees\n        if annee_connue >= annee\n    ]\n\n    if (\n        not inferieures\n        or\n        not superieures\n    ):\n        return None\n\n    annee_basse = max(\n        inferieures\n    )\n\n    annee_haute = min(\n        superieures\n    )\n\n    if (\n        annee_basse\n        ==\n        annee_haute\n    ):\n        return table[\n            annee_basse\n        ]\n\n    valeur_basse = table[\n        annee_basse\n    ]\n\n    valeur_haute = table[\n        annee_haute\n    ]\n\n    proportion = (\n        (annee - annee_basse)\n        /\n        (annee_haute - annee_basse)\n    )\n\n    return round(\n        valeur_basse\n        +\n        (\n            valeur_haute\n            -\n            valeur_basse\n        )\n        *\n        proportion\n    )\n\n\n# ============================================================\n# ESTIMATION APPLE - MACHINE COMPLETE\n# ============================================================\n\ndef construire_estimation_apple(\n    annonce,\n    detection,\n):\n    machine = (\n        detection.get(\n            "machine_apple"\n        )\n        or\n        detecter_machine_apple(\n            annonce\n        )\n    )\n\n    if not machine:\n        return None\n\n    modele = machine.get(\n        "modele"\n    )\n\n    puce = machine.get(\n        "puce"\n    )\n\n    annee = machine.get(\n        "annee"\n    )\n\n    ram = machine.get(\n        "ram"\n    )\n\n    stockage = machine.get(\n        "stockage"\n    )\n\n    ecran = machine.get(\n        "ecran"\n    )\n\n    base = None\n    reference_machine = None\n    confiance_score = 0\n\n    # --------------------------------------------------------\n    # APPLE SILICON\n    # --------------------------------------------------------\n\n    if puce:\n        base = (\n            APPLE_SILICON_BASE.get(\n                (\n                    modele,\n                    puce,\n                )\n            )\n        )\n\n        if base is not None:\n            reference_machine = (\n                f"{modele} {puce}"\n            )\n\n            confiance_score = 70\n\n    # --------------------------------------------------------\n    # INTEL + ANNEE\n    # --------------------------------------------------------\n\n    if (\n        base is None\n        and\n        annee is not None\n    ):\n        base = (\n            trouver_base_intel_apple(\n                modele,\n                annee,\n            )\n        )\n\n        if base is not None:\n            reference_machine = (\n                f"{modele} {annee}"\n            )\n\n            confiance_score = 60\n\n    composants = [\n        valeur\n        for valeur in (\n            modele,\n            puce,\n            machine.get("cpu"),\n            ram,\n            stockage,\n            ecran,\n        )\n        if valeur\n    ]\n\n    # --------------------------------------------------------\n    # MODELE APPLE TROUVE MAIS PAS ASSEZ PRECIS\n    # --------------------------------------------------------\n\n    if base is None:\n        raison = (\n            "Modèle Apple identifié, mais année ou puce "\n            "insuffisante pour une valorisation fiable"\n        )\n\n        estimation = {\n            "statut":\n                "MACHINE_COMPLETE_REQUISE",\n\n            "analyse_autorisee":\n                False,\n\n            "raisons_blocage":\n                [raison],\n\n            "valeur_composants":\n                0,\n\n            "valeur_basse":\n                0,\n\n            "valeur_probable":\n                0,\n\n            "valeur_haute":\n                0,\n\n            "confiance":\n                "🔴 TRÈS FAIBLE",\n\n            "confiance_score":\n                20,\n\n            "categories_detectees":\n                set(),\n\n            "categories_valorisees":\n                set(),\n\n            "categories_fiables":\n                set(),\n\n            "categories_manquantes":\n                set(),\n\n            "categories_critiques_non_fiables":\n                set(),\n\n            "composants_valorises":\n                [],\n\n            "composants_non_valorises":\n                composants,\n\n            "composants_valorisation_non_fiable":\n                [],\n\n            "detection_composants":\n                detection,\n\n            "references_prix_utilisees":\n                {},\n\n            "coherence":\n                {\n                    "coherent":\n                        True,\n\n                    "problemes":\n                        [],\n                },\n\n            "mode_valorisation":\n                "machine_complete_apple",\n\n            "machine":\n                machine,\n        }\n\n        return (\n            0,\n            composants,\n            estimation,\n        )\n\n    # --------------------------------------------------------\n    # CONFIGURATION\n    # --------------------------------------------------------\n\n    ajustements = (\n        ajustement_ram_apple(\n            ram\n        )\n        +\n        ajustement_stockage_apple(\n            stockage,\n            puce=puce,\n        )\n        +\n        ajustement_ecran_apple(\n            modele,\n            ecran,\n        )\n    )\n\n    valeur_probable = (\n        base\n        +\n        ajustements\n    )\n\n    # Fourchette volontairement large :\n    # batterie, clavier, écran, chargeur et état\n    # ne sont pas encore tous scorés.\n    marge_fourchette = max(\n        50,\n        round(\n            valeur_probable\n            * 0.12\n        ),\n    )\n\n    valeur_basse = max(\n        0,\n        valeur_probable\n        -\n        marge_fourchette,\n    )\n\n    valeur_haute = (\n        valeur_probable\n        +\n        marge_fourchette\n    )\n\n    details = sum(\n        valeur is not None\n        for valeur in (\n            ram,\n            stockage,\n            ecran,\n            annee,\n        )\n    )\n\n    confiance_score += min(\n        15,\n        details * 4,\n    )\n\n    confiance_score = min(\n        confiance_score,\n        85,\n    )\n\n    if confiance_score >= 75:\n        confiance = (\n            "🟢 BONNE"\n        )\n\n    elif confiance_score >= 60:\n        confiance = (\n            "🟡 MOYENNE"\n        )\n\n    else:\n        confiance = (\n            "🟠 FAIBLE"\n        )\n\n    estimation = {\n        "statut":\n            "COMPLETE",\n\n        "analyse_autorisee":\n            True,\n\n        "raisons_blocage":\n            [],\n\n        # Apple = machine complète.\n        # Ne pas additionner des composants soudés.\n        "valeur_composants":\n            0,\n\n        "valeur_basse":\n            valeur_basse,\n\n        "valeur_probable":\n            valeur_probable,\n\n        "valeur_haute":\n            valeur_haute,\n\n        "confiance":\n            confiance,\n\n        "confiance_score":\n            confiance_score,\n\n        "categories_detectees":\n            set(),\n\n        "categories_valorisees":\n            set(),\n\n        "categories_fiables":\n            set(),\n\n        "categories_manquantes":\n            set(),\n\n        "categories_critiques_non_fiables":\n            set(),\n\n        "composants_valorises":\n            composants,\n\n        "composants_non_valorises":\n            [],\n\n        "composants_valorisation_non_fiable":\n            [],\n\n        "detection_composants":\n            detection,\n\n        "references_prix_utilisees":\n            {\n                "machine":\n                    reference_machine,\n            },\n\n        "coherence":\n            {\n                "coherent":\n                    True,\n\n                "problemes":\n                    [],\n            },\n\n        "mode_valorisation":\n            "machine_complete_apple",\n\n        "machine":\n            machine,\n\n        "base_machine":\n            base,\n\n        "ajustements_configuration":\n            ajustements,\n    }\n\n    return (\n        valeur_probable,\n        composants,\n        estimation,\n    )\n\n\n\n\n# ============================================================\n# PORTABLE WINDOWS - MACHINE COMPLETE\n#\n# Bases internes prudentes, calibrées pour donner un ordre\n# de grandeur. Ce ne sont pas des prix de vente garantis.\n# ============================================================\n\nPORTABLE_GPU_BASE = {\n    "GTX 960M": 210,\n    "GTX 1050": 240,\n    "GTX 1050 Ti": 290,\n    "GTX 1060": 330,\n    "GTX 1070": 360,\n    "GTX 1650": 360,\n    "GTX 1650 Ti": 390,\n    "GTX 1660 Ti": 430,\n    "RTX 2060": 440,\n    "RTX 3050": 450,\n    "RTX 3050 Ti": 480,\n    "RTX 3060": 560,\n    "RTX 3070": 650,\n    "RTX 3070 Ti": 720,\n    "RTX 3080": 760,\n    "RTX 4050": 620,\n    "RTX 4060": 760,\n    "RTX 4070": 950,\n    "RTX 4080": 1350,\n    "RTX 4090": 1750,\n}\n\n\ndef extraire_generation_intel(cpu):\n    if not cpu:\n        return None\n\n    match = re.search(\n        r"\\bi[3579]-(\\d{4,5})",\n        str(cpu),\n        flags=re.IGNORECASE,\n    )\n\n    if not match:\n        return None\n\n    modele = match.group(1)\n\n    if len(modele) == 4:\n        return int(\n            modele[0]\n        )\n\n    if len(modele) == 5:\n        return int(\n            modele[:2]\n        )\n\n    return None\n\n\ndef extraire_serie_ryzen(cpu):\n    if not cpu:\n        return None\n\n    match = re.search(\n        r"\\bRyzen\\s+[3579]\\s+(\\d{4,5})",\n        str(cpu),\n        flags=re.IGNORECASE,\n    )\n\n    if not match:\n        return None\n\n    modele = match.group(1)\n\n    try:\n        return int(\n            modele[0]\n        )\n\n    except (\n        TypeError,\n        ValueError,\n    ):\n        return None\n\n\ndef ajustement_cpu_portable(cpu):\n    if not cpu:\n        return None\n\n    cpu_texte = str(\n        cpu\n    )\n\n    generation_intel = (\n        extraire_generation_intel(\n            cpu_texte\n        )\n    )\n\n    if generation_intel is not None:\n        if generation_intel <= 6:\n            ajustement_generation = -30\n\n        elif generation_intel == 7:\n            ajustement_generation = -20\n\n        elif generation_intel in {\n            8,\n            9,\n        }:\n            ajustement_generation = 0\n\n        elif generation_intel in {\n            10,\n            11,\n        }:\n            ajustement_generation = 30\n\n        elif generation_intel == 12:\n            ajustement_generation = 60\n\n        elif generation_intel == 13:\n            ajustement_generation = 90\n\n        else:\n            ajustement_generation = 120\n\n        if cpu_texte.lower().startswith(\n            "i3-"\n        ):\n            ajustement_famille = -40\n\n        elif cpu_texte.lower().startswith(\n            "i7-"\n        ):\n            ajustement_famille = 35\n\n        elif cpu_texte.lower().startswith(\n            "i9-"\n        ):\n            ajustement_famille = 80\n\n        else:\n            ajustement_famille = 0\n\n        return (\n            ajustement_generation\n            +\n            ajustement_famille\n        )\n\n    serie_ryzen = (\n        extraire_serie_ryzen(\n            cpu_texte\n        )\n    )\n\n    if serie_ryzen is not None:\n        ajustements_series = {\n            3: -10,\n            4: 10,\n            5: 35,\n            6: 60,\n            7: 90,\n            8: 120,\n            9: 140,\n        }\n\n        ajustement_generation = (\n            ajustements_series.get(\n                serie_ryzen,\n                0,\n            )\n        )\n\n        if re.search(\n            r"\\bRyzen\\s+3\\b",\n            cpu_texte,\n            flags=re.IGNORECASE,\n        ):\n            ajustement_famille = -35\n\n        elif re.search(\n            r"\\bRyzen\\s+7\\b",\n            cpu_texte,\n            flags=re.IGNORECASE,\n        ):\n            ajustement_famille = 35\n\n        elif re.search(\n            r"\\bRyzen\\s+9\\b",\n            cpu_texte,\n            flags=re.IGNORECASE,\n        ):\n            ajustement_famille = 80\n\n        else:\n            ajustement_famille = 0\n\n        return (\n            ajustement_generation\n            +\n            ajustement_famille\n        )\n\n    return None\n\n\ndef base_portable_bureautique(cpu):\n    """\n    Base prudente pour un portable sans GPU dédié.\n    Un CPU précis est obligatoire.\n    """\n\n    if not cpu:\n        return None\n\n    cpu_texte = str(\n        cpu\n    )\n\n    generation = (\n        extraire_generation_intel(\n            cpu_texte\n        )\n    )\n\n    if generation is not None:\n        if generation <= 5:\n            base = 100\n\n        elif generation <= 7:\n            base = 140\n\n        elif generation <= 9:\n            base = 190\n\n        elif generation <= 11:\n            base = 260\n\n        elif generation == 12:\n            base = 330\n\n        elif generation == 13:\n            base = 400\n\n        else:\n            base = 460\n\n        if cpu_texte.lower().startswith(\n            "i3-"\n        ):\n            base -= 40\n\n        elif cpu_texte.lower().startswith(\n            "i7-"\n        ):\n            base += 45\n\n        elif cpu_texte.lower().startswith(\n            "i9-"\n        ):\n            base += 90\n\n        return max(\n            70,\n            base,\n        )\n\n    serie_ryzen = (\n        extraire_serie_ryzen(\n            cpu_texte\n        )\n    )\n\n    if serie_ryzen is not None:\n        bases = {\n            3: 170,\n            4: 220,\n            5: 280,\n            6: 340,\n            7: 420,\n            8: 500,\n            9: 560,\n        }\n\n        base = bases.get(\n            serie_ryzen\n        )\n\n        if base is None:\n            return None\n\n        if re.search(\n            r"\\bRyzen\\s+3\\b",\n            cpu_texte,\n            flags=re.IGNORECASE,\n        ):\n            base -= 35\n\n        elif re.search(\n            r"\\bRyzen\\s+7\\b",\n            cpu_texte,\n            flags=re.IGNORECASE,\n        ):\n            base += 45\n\n        elif re.search(\n            r"\\bRyzen\\s+9\\b",\n            cpu_texte,\n            flags=re.IGNORECASE,\n        ):\n            base += 90\n\n        return max(\n            90,\n            base,\n        )\n\n    return None\n\n\ndef ajustement_ram_portable(ram):\n    quantite = extraire_nombre_go(\n        ram\n    )\n\n    if quantite is None:\n        return 0\n\n    if quantite >= 64:\n        return 140\n\n    if quantite >= 32:\n        return 80\n\n    if quantite >= 24:\n        return 55\n\n    if quantite >= 16:\n        return 35\n\n    if quantite <= 4:\n        return -40\n\n    return 0\n\n\ndef ajustement_stockage_portable(\n    stockage,\n):\n    if not stockage:\n        return 0\n\n    texte = str(\n        stockage\n    ).lower()\n\n    capacite = stockage_en_go(\n        stockage\n    )\n\n    if capacite is None:\n        return 0\n\n    # SSD/NVMe : prime de capacité.\n    if (\n        "ssd" in texte\n        or\n        "nvme" in texte\n    ):\n        if capacite >= 2048:\n            return 100\n\n        if capacite >= 1024:\n            return 60\n\n        if capacite >= 512:\n            return 30\n\n        if capacite <= 128:\n            return -20\n\n        return 0\n\n    # HDD seul : faible valeur ajoutée.\n    if (\n        "hdd" in texte\n        and\n        capacite >= 1024\n    ):\n        return 10\n\n    return 0\n\n\ndef ajustement_gamme_portable(\n    gamme,\n):\n    if not gamme:\n        return 0\n\n    premium = {\n        "ROG Zephyrus": 70,\n        "ROG Strix": 50,\n        "ROG": 35,\n        "Legion": 45,\n        "Predator": 35,\n        "Alienware": 70,\n        "Blade": 80,\n        "AORUS": 40,\n        "XPS": 55,\n        "GS": 35,\n        "Omen": 25,\n    }\n\n    return premium.get(\n        gamme,\n        0,\n    )\n\n\ndef ajustement_ecran_portable(\n    machine,\n):\n    ajustement = 0\n\n    ecran = machine.get(\n        "ecran"\n    )\n\n    frequence = machine.get(\n        "frequence_ecran"\n    )\n\n    if ecran:\n        try:\n            taille = float(\n                str(ecran)\n                .replace(\n                    " pouces",\n                    "",\n                )\n            )\n\n            if taille >= 17:\n                ajustement += 15\n\n        except ValueError:\n            pass\n\n    if frequence:\n        match = re.search(\n            r"(\\d+)",\n            str(frequence),\n        )\n\n        if match:\n            hz = int(\n                match.group(1)\n            )\n\n            if hz >= 240:\n                ajustement += 45\n\n            elif hz >= 165:\n                ajustement += 35\n\n            elif hz >= 144:\n                ajustement += 25\n\n            elif hz >= 120:\n                ajustement += 15\n\n    return ajustement\n\n\ndef construire_estimation_portable_windows(\n    annonce,\n    detection,\n):\n    machine = (\n        detection.get(\n            "machine_portable_windows"\n        )\n        or\n        detecter_machine_portable_windows(\n            annonce\n        )\n    )\n\n    if not machine:\n        return None\n\n    cpu = machine.get(\n        "cpu"\n    )\n\n    gpu = machine.get(\n        "gpu"\n    )\n\n    ram = machine.get(\n        "ram"\n    )\n\n    stockage = machine.get(\n        "stockage"\n    )\n\n    gamme = machine.get(\n        "gamme"\n    )\n\n    composants = [\n        valeur\n        for valeur in (\n            machine.get("marque"),\n            gamme,\n            gpu,\n            cpu,\n            ram,\n            stockage,\n            machine.get("ecran"),\n            machine.get("frequence_ecran"),\n        )\n        if valeur\n    ]\n\n    raisons_blocage = []\n    base = None\n    reference_machine = None\n    confiance_score = 0\n\n    # --------------------------------------------------------\n    # PORTABLE AVEC GPU DEDIE\n    # --------------------------------------------------------\n\n    if gpu:\n        base = PORTABLE_GPU_BASE.get(\n            gpu\n        )\n\n        if base is None:\n            raisons_blocage.append(\n                "GPU portable détecté mais aucune "\n                "base de valorisation fiable n\'est disponible"\n            )\n\n        if cpu is None:\n            raisons_blocage.append(\n                "CPU précis manquant pour valoriser "\n                "le portable gaming"\n            )\n\n        if (\n            base is not None\n            and\n            cpu is not None\n        ):\n            reference_machine = (\n                f"portable GPU {gpu}"\n            )\n\n            ajustement_cpu = (\n                ajustement_cpu_portable(\n                    cpu\n                )\n            )\n\n            if ajustement_cpu is None:\n                raisons_blocage.append(\n                    "Génération CPU portable non reconnue"\n                )\n\n            else:\n                base += ajustement_cpu\n                confiance_score = 68\n\n    # --------------------------------------------------------\n    # PORTABLE SANS GPU DEDIE\n    # --------------------------------------------------------\n\n    else:\n        if est_gaming(\n            annonce\n        ):\n            raisons_blocage.append(\n                "Portable gaming annoncé mais GPU "\n                "dédié non identifié"\n            )\n\n        else:\n            base = (\n                base_portable_bureautique(\n                    cpu\n                )\n            )\n\n            if base is None:\n                raisons_blocage.append(\n                    "CPU précis requis pour valoriser "\n                    "ce portable"\n                )\n\n            else:\n                reference_machine = (\n                    f"portable CPU {cpu}"\n                )\n\n                confiance_score = 55\n\n    # --------------------------------------------------------\n    # BLOCAGE SI BASE INSUFFISANTE\n    # --------------------------------------------------------\n\n    if (\n        base is None\n        or raisons_blocage\n    ):\n        estimation = {\n            "statut":\n                "MACHINE_COMPLETE_REQUISE",\n\n            "analyse_autorisee":\n                False,\n\n            "raisons_blocage":\n                raisons_blocage\n                or [\n                    "Informations insuffisantes pour "\n                    "valoriser ce portable"\n                ],\n\n            "valeur_composants":\n                0,\n\n            "valeur_basse":\n                0,\n\n            "valeur_probable":\n                0,\n\n            "valeur_haute":\n                0,\n\n            "confiance":\n                "🔴 TRÈS FAIBLE",\n\n            "confiance_score":\n                20,\n\n            "categories_detectees":\n                {\n                    categorie\n                    for categorie in (\n                        "gpu",\n                        "cpu",\n                        "ram",\n                        "stockage",\n                    )\n                    if detection.get(\n                        categorie\n                    )\n                },\n\n            "categories_valorisees":\n                set(),\n\n            "categories_fiables":\n                set(),\n\n            "categories_manquantes":\n                set(),\n\n            "categories_critiques_non_fiables":\n                set(),\n\n            "composants_valorises":\n                [],\n\n            "composants_non_valorises":\n                composants,\n\n            "composants_valorisation_non_fiable":\n                [],\n\n            "detection_composants":\n                detection,\n\n            "references_prix_utilisees":\n                {},\n\n            "coherence":\n                {\n                    "coherent":\n                        True,\n\n                    "problemes":\n                        [],\n                },\n\n            "mode_valorisation":\n                "machine_complete_portable_windows",\n\n            "machine":\n                machine,\n        }\n\n        return (\n            0,\n            composants,\n            estimation,\n        )\n\n    # --------------------------------------------------------\n    # AJUSTEMENTS CONFIGURATION\n    # --------------------------------------------------------\n\n    valeur_probable = (\n        base\n        +\n        ajustement_ram_portable(\n            ram\n        )\n        +\n        ajustement_stockage_portable(\n            stockage\n        )\n        +\n        ajustement_gamme_portable(\n            gamme\n        )\n        +\n        ajustement_ecran_portable(\n            machine\n        )\n    )\n\n    valeur_probable = max(\n        70,\n        round(\n            valeur_probable\n        ),\n    )\n\n    # Fourchette plus large que sur un desktop :\n    # état de batterie, écran, châssis, TGP GPU et modèle exact\n    # influencent fortement un portable.\n    pourcentage = (\n        0.16\n        if gpu\n        else 0.20\n    )\n\n    marge_fourchette = max(\n        50,\n        round(\n            valeur_probable\n            * pourcentage\n        ),\n    )\n\n    valeur_basse = max(\n        0,\n        valeur_probable\n        -\n        marge_fourchette,\n    )\n\n    valeur_haute = (\n        valeur_probable\n        +\n        marge_fourchette\n    )\n\n    details = sum(\n        valeur is not None\n        for valeur in (\n            ram,\n            stockage,\n            machine.get(\n                "ecran"\n            ),\n            machine.get(\n                "frequence_ecran"\n            ),\n            gamme,\n        )\n    )\n\n    confiance_score += min(\n        17,\n        details * 3,\n    )\n\n    confiance_score = min(\n        85,\n        confiance_score,\n    )\n\n    if confiance_score >= 75:\n        confiance = (\n            "🟢 BONNE"\n        )\n\n    elif confiance_score >= 60:\n        confiance = (\n            "🟡 MOYENNE"\n        )\n\n    else:\n        confiance = (\n            "🟠 FAIBLE"\n        )\n\n    categories_detectees = {\n        categorie\n        for categorie in (\n            "gpu",\n            "cpu",\n            "ram",\n            "stockage",\n        )\n        if detection.get(\n            categorie\n        )\n    }\n\n    estimation = {\n        "statut":\n            "COMPLETE",\n\n        "analyse_autorisee":\n            True,\n\n        "raisons_blocage":\n            [],\n\n        # Portable = valeur machine complète.\n        "valeur_composants":\n            0,\n\n        "valeur_basse":\n            valeur_basse,\n\n        "valeur_probable":\n            valeur_probable,\n\n        "valeur_haute":\n            valeur_haute,\n\n        "confiance":\n            confiance,\n\n        "confiance_score":\n            confiance_score,\n\n        "categories_detectees":\n            categories_detectees,\n\n        "categories_valorisees":\n            categories_detectees,\n\n        "categories_fiables":\n            categories_detectees,\n\n        "categories_manquantes":\n            set(),\n\n        "categories_critiques_non_fiables":\n            set(),\n\n        "composants_valorises":\n            composants,\n\n        "composants_non_valorises":\n            [],\n\n        "composants_valorisation_non_fiable":\n            [],\n\n        "detection_composants":\n            detection,\n\n        "references_prix_utilisees":\n            {\n                "machine":\n                    reference_machine,\n            },\n\n        "coherence":\n            {\n                "coherent":\n                    True,\n\n                "problemes":\n                    [],\n            },\n\n        "mode_valorisation":\n            "machine_complete_portable_windows",\n\n        "machine":\n            machine,\n\n        "base_machine":\n            base,\n    }\n\n    return (\n        valeur_probable,\n        composants,\n        estimation,\n    )\n\n\n# ============================================================\n# MACHINE COMPLETE A VALORISER PLUS TARD\n# ============================================================\n\ndef estimation_machine_complete_requise(\n    annonce,\n    detection,\n    raison,\n):\n    composants = []\n\n    for categorie in (\n        "gpu",\n        "cpu",\n        "ram",\n        "stockage",\n    ):\n        valeurs = detection.get(\n            categorie,\n            [],\n        )\n\n        if valeurs:\n            composants.append(\n                valeurs[0]\n            )\n\n    categories_detectees = {\n        categorie\n        for categorie in (\n            "gpu",\n            "cpu",\n            "ram",\n            "stockage",\n        )\n        if detection.get(\n            categorie\n        )\n    }\n\n    estimation = {\n        "statut":\n            "MACHINE_COMPLETE_REQUISE",\n\n        "analyse_autorisee":\n            False,\n\n        "raisons_blocage":\n            [raison],\n\n        "valeur_composants":\n            0,\n\n        "valeur_basse":\n            0,\n\n        "valeur_probable":\n            0,\n\n        "valeur_haute":\n            0,\n\n        "confiance":\n            "🔴 TRÈS FAIBLE",\n\n        "confiance_score":\n            20,\n\n        "categories_detectees":\n            categories_detectees,\n\n        "categories_valorisees":\n            set(),\n\n        "categories_fiables":\n            set(),\n\n        "categories_manquantes":\n            set(),\n\n        "categories_critiques_non_fiables":\n            set(),\n\n        "composants_valorises":\n            [],\n\n        "composants_non_valorises":\n            composants,\n\n        "composants_valorisation_non_fiable":\n            [],\n\n        "detection_composants":\n            detection,\n\n        "references_prix_utilisees":\n            {},\n\n        "coherence":\n            {\n                "coherent":\n                    True,\n\n                "problemes":\n                    [],\n            },\n\n        "mode_valorisation":\n            "machine_complete_requise",\n    }\n\n    return (\n        0,\n        composants,\n        estimation,\n    )\n\n\n# ============================================================\n# DESKTOP - VALORISATION PAR COMPOSANTS\n# ============================================================\n\ndef estimer_desktop_par_composants(\n    annonce,\n    detection,\n):\n    coherence = verifier_coherence(\n        annonce,\n        detection,\n    )\n\n    valeur_composants = 0\n\n    composants = []\n    composants_valorises = []\n    composants_non_valorises = []\n    composants_valorisation_non_fiable = []\n\n    categories_detectees = set()\n    categories_valorisees = set()\n    categories_fiables = set()\n\n    references_prix_utilisees = {}\n\n    ordre_categories = (\n        "gpu",\n        "cpu",\n        "ram",\n        "stockage",\n    )\n\n    for categorie in ordre_categories:\n        valeurs_detectees = (\n            detection.get(\n                categorie,\n                [],\n            )\n        )\n\n        if not valeurs_detectees:\n            continue\n\n        valeur_detectee = (\n            valeurs_detectees[0]\n        )\n\n        categories_detectees.add(\n            categorie\n        )\n\n        composants.append(\n            valeur_detectee\n        )\n\n        (\n            reference_prix,\n            infos,\n        ) = trouver_reference_prix(\n            categorie,\n            valeur_detectee,\n        )\n\n        if infos is None:\n            composants_non_valorises.append(\n                valeur_detectee\n            )\n\n            continue\n\n        references_prix_utilisees[\n            valeur_detectee\n        ] = reference_prix\n\n        prix = infos.get(\n            "prix"\n        )\n\n        valorisation_fiable = (\n            infos.get(\n                "valorisation_fiable",\n                False,\n            )\n        )\n\n        if isinstance(\n            prix,\n            (int, float),\n        ):\n            valeur_composants += prix\n\n            categories_valorisees.add(\n                categorie\n            )\n\n            composants_valorises.append(\n                valeur_detectee\n            )\n\n            if valorisation_fiable:\n                categories_fiables.add(\n                    categorie\n                )\n\n            else:\n                composants_valorisation_non_fiable.append(\n                    valeur_detectee\n                )\n\n        else:\n            composants_non_valorises.append(\n                valeur_detectee\n            )\n\n    categories_manquantes = (\n        CATEGORIES_PRINCIPALES\n        -\n        categories_detectees\n    )\n\n    # CPU obligatoire pour un desktop complet.\n    categories_critiques = {\n        "cpu",\n    }\n\n    # Pour un PC gaming, GPU obligatoire.\n    # Pour un PC complet non gaming, si un GPU est déclaré,\n    # sa valorisation doit également être fiable.\n    if (\n        est_gaming(\n            annonce\n        )\n        or\n        detection.get(\n            "gpu"\n        )\n    ):\n        categories_critiques.add(\n            "gpu"\n        )\n\n    categories_critiques_non_fiables = (\n        categories_critiques\n        -\n        categories_fiables\n    )\n\n    raisons_blocage = []\n\n    for categorie in sorted(\n        categories_critiques_non_fiables\n    ):\n        raisons_blocage.append(\n            f"Valorisation "\n            f"{categorie.upper()} "\n            "insuffisamment fiable"\n        )\n\n    if not coherence.get(\n        "coherent",\n        True,\n    ):\n        for probleme in coherence.get(\n            "problemes",\n            [],\n        ):\n            raisons_blocage.append(\n                probleme\n            )\n\n    analyse_autorisee = (\n        not\n        categories_critiques_non_fiables\n        and\n        coherence.get(\n            "coherent",\n            True,\n        )\n    )\n\n    if valeur_composants > 0:\n        valeur_basse = (\n            valeur_composants\n            + 50\n        )\n\n        valeur_probable = (\n            valeur_composants\n            + 100\n        )\n\n        valeur_haute = (\n            valeur_composants\n            + 150\n            + (\n                len(\n                    categories_manquantes\n                )\n                * 50\n            )\n        )\n\n    else:\n        valeur_basse = 0\n        valeur_probable = 0\n        valeur_haute = 0\n\n    nombre_categories_fiables = len(\n        categories_fiables\n    )\n\n    if nombre_categories_fiables >= 4:\n        confiance = (\n            "🟢 BONNE"\n        )\n        confiance_score = 80\n\n    elif nombre_categories_fiables == 3:\n        confiance = (\n            "🟡 MOYENNE"\n        )\n        confiance_score = 60\n\n    elif nombre_categories_fiables == 2:\n        confiance = (\n            "🟠 FAIBLE"\n        )\n        confiance_score = 40\n\n    else:\n        confiance = (\n            "🔴 TRÈS FAIBLE"\n        )\n        confiance_score = 20\n\n    if not analyse_autorisee:\n        confiance_score = min(\n            confiance_score,\n            40,\n        )\n\n        if confiance_score <= 20:\n            confiance = (\n                "🔴 TRÈS FAIBLE"\n            )\n\n        else:\n            confiance = (\n                "🟠 FAIBLE"\n            )\n\n    statut = (\n        "COMPLETE"\n        if analyse_autorisee\n        else "INCOMPLETE"\n    )\n\n    estimation = {\n        "statut":\n            statut,\n\n        "analyse_autorisee":\n            analyse_autorisee,\n\n        "raisons_blocage":\n            raisons_blocage,\n\n        "valeur_composants":\n            valeur_composants,\n\n        "valeur_basse":\n            valeur_basse,\n\n        "valeur_probable":\n            valeur_probable,\n\n        "valeur_haute":\n            valeur_haute,\n\n        "confiance":\n            confiance,\n\n        "confiance_score":\n            confiance_score,\n\n        "categories_detectees":\n            categories_detectees,\n\n        "categories_valorisees":\n            categories_valorisees,\n\n        "categories_fiables":\n            categories_fiables,\n\n        "categories_manquantes":\n            categories_manquantes,\n\n        "categories_critiques_non_fiables":\n            categories_critiques_non_fiables,\n\n        "composants_valorises":\n            composants_valorises,\n\n        "composants_non_valorises":\n            composants_non_valorises,\n\n        "composants_valorisation_non_fiable":\n            composants_valorisation_non_fiable,\n\n        "detection_composants":\n            detection,\n\n        "references_prix_utilisees":\n            references_prix_utilisees,\n\n        "coherence":\n            coherence,\n\n        "mode_valorisation":\n            "composants_desktop",\n    }\n\n    return (\n        valeur_probable,\n        composants,\n        estimation,\n    )\n\n\n# ============================================================\n# FONCTION PRINCIPALE\n# ============================================================\n\ndef estimer_valeur(annonce):\n    detection = detecter_composants(\n        annonce\n    )\n\n    # ========================================================\n    # 1. APPLE\n    #\n    # MacBook / iMac / Mac mini / Mac Studio :\n    # valorisation comme MACHINE COMPLETE.\n    # ========================================================\n\n    if detection.get(\n        "machine_apple"\n    ):\n        resultat_apple = (\n            construire_estimation_apple(\n                annonce,\n                detection,\n            )\n        )\n\n        if resultat_apple is not None:\n            return resultat_apple\n\n    # ========================================================\n    # 2. PORTABLE WINDOWS\n    #\n    # Toujours protégé pour l\'instant.\n    # On ajoutera son moteur de comparables séparément.\n    # ========================================================\n\n    if est_portable_windows(\n        annonce\n    ):\n        resultat_portable = (\n            construire_estimation_portable_windows(\n                annonce,\n                detection,\n            )\n        )\n\n        if resultat_portable is not None:\n            return resultat_portable\n\n        return (\n            estimation_machine_complete_requise(\n                annonce,\n                detection,\n                (\n                    "Portable : informations insuffisantes "\n                    "pour une valorisation fiable"\n                ),\n            )\n        )\n\n    # ========================================================\n    # 3. TOUT-EN-UN NON APPLE\n    # ========================================================\n\n    if est_tout_en_un(\n        annonce\n    ):\n        return (\n            estimation_machine_complete_requise(\n                annonce,\n                detection,\n                (\n                    "Tout-en-un : valorisation par "\n                    "machine complète requise"\n                ),\n            )\n        )\n\n    # ========================================================\n    # 4. DESKTOP CLASSIQUE\n    # ========================================================\n\n    return (\n        estimer_desktop_par_composants(\n            annonce,\n            detection,\n        )\n    )\n'

